import React, { useEffect, useRef } from 'react'
import {
  Engine,
  Scene,
  ArcRotateCamera,
  HemisphericLight,
  Vector3,
  SceneLoader,
  AbstractMesh,
  Color4,
} from '@babylonjs/core'
import '@babylonjs/loaders/glTF'

export interface GlbEditorProps {
  glbBlob: Blob
  onMeshSelected?: (meshName: string) => void
  className?: string
  style?: React.CSSProperties
}

const GlbEditor: React.FC<GlbEditorProps> = ({ 
  glbBlob, 
  onMeshSelected,
  className = 'glb-canvas',
  style
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const engineRef = useRef<Engine | null>(null)
  const sceneRef = useRef<Scene | null>(null)

  useEffect(() => {
    if (!canvasRef.current) return

    // Create engine and scene
    const engine = new Engine(canvasRef.current, true, {
      preserveDrawingBuffer: true,
      stencil: true,
    })
    engineRef.current = engine

    const scene = new Scene(engine)
    scene.clearColor = new Color4(0.1, 0.1, 0.1, 1)
    sceneRef.current = scene

    // Create camera
    const camera = new ArcRotateCamera(
      'camera',
      -Math.PI / 2,
      Math.PI / 2.5,
      5,
      Vector3.Zero(),
      scene
    )
    camera.attachControl(canvasRef.current, true)
    camera.wheelPrecision = 50
    camera.minZ = 0.01
    camera.lowerRadiusLimit = 0.1
    camera.upperRadiusLimit = 100

    // Create lighting
    const light = new HemisphericLight('light', new Vector3(0, 1, 0), scene)
    light.intensity = 1.2

    // Load GLB from blob
    const url = URL.createObjectURL(glbBlob);
        
    // Use an async IIFE (Immediately Invoked Function Expression)
    (async () => {
      try {
        const result = await SceneLoader.ImportMeshAsync("", "", url, scene, undefined, ".glb");
        const meshes = result.meshes;
        
        console.log('Loaded meshes:', meshes.length);

        // Filter out empty/null meshes
        const validMeshes = meshes.filter(m => m && m.getTotalVertices() > 0);

        if (validMeshes.length === 0) {
          console.warn('No valid meshes found in GLB');
          return;
        }

        // Fit model in camera frustum
        fitModelInFrustum(validMeshes, camera, scene);

        // Enable mesh selection
        setupMeshSelection(validMeshes, scene, onMeshSelected);

        // Cleanup blob URL
        URL.revokeObjectURL(url);
      } catch (error) {
        console.error('Error loading GLB:', error);
        URL.revokeObjectURL(url);
      }
    })();

    // Handle mesh click selection
    scene.onPointerDown = (_evt, pickResult) => {
      if (pickResult.hit && pickResult.pickedMesh) {
        const mesh = pickResult.pickedMesh
        if (mesh.name && mesh.name !== '__root__') {
          console.log('Mesh clicked:', mesh.name)
          if (onMeshSelected) {
            onMeshSelected(mesh.name)
          }
        }
      }
    }

    // Render loop
    engine.runRenderLoop(() => {
      scene.render()
    })

    // Handle resize
    const handleResize = () => {
      engine.resize()
    }
    window.addEventListener('resize', handleResize)

    // Cleanup
    return () => {
      window.removeEventListener('resize', handleResize)
      scene.dispose()
      engine.dispose()
    }
  }, [glbBlob, onMeshSelected])

  return <canvas ref={canvasRef} className={className} style={style} />
}

// Helper function to fit model in camera frustum
function fitModelInFrustum(
  meshes: AbstractMesh[],
  camera: ArcRotateCamera,
  _scene: Scene
) {
  if (meshes.length === 0) return

  // Calculate bounding box for all meshes
  let min = new Vector3(Infinity, Infinity, Infinity)
  let max = new Vector3(-Infinity, -Infinity, -Infinity)

  meshes.forEach((mesh) => {
    const boundingInfo = mesh.getBoundingInfo()
    const meshMin = boundingInfo.boundingBox.minimumWorld
    const meshMax = boundingInfo.boundingBox.maximumWorld

    min = Vector3.Minimize(min, meshMin)
    max = Vector3.Maximize(max, meshMax)
  })

  // Calculate center and size
  const center = Vector3.Center(min, max)
  const size = max.subtract(min)
  const maxDimension = Math.max(size.x, size.y, size.z)

  // Set camera target to center
  camera.target = center

  // Calculate appropriate camera distance
  const distance = maxDimension * 2.5
  camera.radius = distance

  // Adjust camera limits
  camera.lowerRadiusLimit = maxDimension * 0.5
  camera.upperRadiusLimit = maxDimension * 10

  console.log('Model fitted:', {
    center: center.asArray(),
    size: size.asArray(),
    maxDimension,
    cameraDistance: distance,
  })
}

// Helper function to setup mesh selection
function setupMeshSelection(
  meshes: AbstractMesh[],
  _scene: Scene,
  _onMeshSelected?: (meshName: string) => void
) {
  meshes.forEach((mesh) => {
    // Make meshes pickable
    mesh.isPickable = true

    // Add hover effect
    mesh.actionManager = null // Clear any existing action manager
  })

  console.log('Mesh selection enabled for', meshes.length, 'meshes')
}

export default GlbEditor
